// The wasm-bindgen glue for crates/quicktype-wasm, generated by
// script/build.mjs (`wasm-bindgen --target web`, wrapped in a factory so
// that every instance has its own glue state). The build writes a CommonJS
// copy to dist/native/wasm/glue.js and an ES module copy to
// dist/esm/native/wasm/glue.js; the .wasm file is
// dist/native/wasm/quicktype_wasm_bg.wasm.

/** The exports of crates/quicktype-wasm (see its crate documentation). */
export interface WasmGlue {
    initSync(options: { module: unknown }): unknown;
    runSync(request: unknown, host: unknown): unknown;
    start(request: unknown, host: unknown): number;
    poll(id: number): unknown;
    settle(id: number, callId: number, ok: boolean, value: unknown): void;
    engineVersion(): string;
    __pow(x: number, y: number): number;
    __panicForTests(): void;
}

/** A fresh, uninitialized copy of the glue. */
export declare function createGlue(): WasmGlue;

/** Where the .wasm file is: a path (CommonJS) or a URL (ES modules). */
export declare function wasmLocation(): unknown;
